-- ============================================================
-- IVORY HUB - Classic API compatibility layer
-- Wraps the AirFlow UI engine so existing game scripts work unchanged.
-- ============================================================
local Library = {}
local Engine = k
local EngineWin = nil
local Unloaded = false
local OnUnloadFns = {}
Library.Flags = Engine.Flags
Library.Toggles = {}
Library.ThemePresets = Engine.ThemePresets
Library.Unloaded = false
Library.NotifySide = "Right"
Library.ShowCustomCursor = false
Library.CornerRadius = 10
Library.ScreenGui = nil
Library.KeybindFrame = nil
Library.ToggleKeybind = nil
Library.UnloadCallback = nil
Library.ContentColumns = 2
Library._windows = {}
Library.Scheme = {
    Accent = Color3.fromRGB(255, 183, 197),
    Background = Color3.fromRGB(23, 14, 19),
    Text = Color3.fromRGB(247, 231, 237),
    CornerRadius = 10,
}

local function sc(a, b)
    if a == Library then return b end
    return a
end

local function norm(a, b)
    local cfg = {}
    if type(a) == "string" then
        cfg = type(b) == "table" and b or {}
        cfg.Flag = cfg.Flag or a
        cfg.Name = cfg.Name or cfg.Text or cfg.Title or a
    elseif type(a) == "table" then
        cfg = a
        cfg.Name = cfg.Name or cfg.Text or cfg.Title or cfg.Content or "Element"
    else
        cfg = { Name = "Element" }
    end
    cfg.Default = cfg.Default or cfg.CurrentValue or cfg.Value
    if cfg.Range then
        cfg.Min = cfg.Min or cfg.Range[1]
        cfg.Max = cfg.Max or cfg.Range[2]
    end
    cfg.Increment = cfg.Increment or cfg.Rounding or 1
    if cfg.Options and not cfg.Values then cfg.Values = cfg.Options end
    if cfg.CurrentOption then cfg.Default = cfg.CurrentOption end
    if cfg.Color then cfg.Default = cfg.Color end
    if cfg.CurrentKeybind then cfg.Default = cfg.CurrentKeybind end
    cfg.Placeholder = cfg.Placeholder or cfg.PlaceholderText
    return cfg
end

local function wrapElem(e, kind)
    if not e then return e end
    if e.Set and not e.SetValue then
        e.SetValue = function(self, v, ...) self:Set(v, ...) end
    end
    if e.Set and not e.SetText then
        e.SetText = function(self, v) self:Set(v) end
    end
    if e.Set and not e.SetName then
        e.SetName = function(self, v) self:Set(v) end
    end
    if kind == "Toggle" then
        e._cb = {}
        local os_ = e.Set
        if os_ then
            e.Set = function(self, v, silent)
                os_(self, v, silent)
                if not silent then
                    for _, fn in ipairs(self._cb) do pcall(fn, self.Value) end
                end
            end
            e.SetValue = e.Set
        end
        e.OnChanged = function(self, fn) table.insert(self._cb, fn) end
        e.FireChanged = function(self)
            for _, fn in ipairs(self._cb) do pcall(fn, self.Value) end
        end
    end
    return e
end

-- Container = Tab or Section. getBox returns the engine groupbox.
-- parentTab is the engine tab object so nested sections land on the right tab.
local function makeContainer(getBox, parentTab)
    local c = {}
    local lazyBox = nil
    local function box()
        if not lazyBox then lazyBox = getBox() end
        return lazyBox
    end

    function c:CreateSection(a)
        local name = type(a) == "table" and (a.Name or a.Title or "Section") or tostring(a or "Section")
        local pt = parentTab
        if not pt then return makeContainer(function() return box() end, nil) end
        local nb = pt:AddLeftGroupbox({ Name = name })
        return makeContainer(function() return nb end, pt)
    end

    function c:CreateButton(a, b)
        local cfg = norm(a, b)
        if type(a) == "string" and type(b) == "function" then cfg.Name = a cfg.Callback = b end
        local bx = box()
        if not bx then return nil end
        return wrapElem(bx:Button({ Name = cfg.Name, Callback = cfg.Callback, Icon = cfg.Icon }), "Button")
    end

    function c:CreateToggle(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        local e = bx:Toggle({ Name = cfg.Name, Default = cfg.Default or false, Callback = cfg.Callback, Flag = cfg.Flag })
        if cfg.Flag and e then Library.Toggles[cfg.Flag] = e end
        return wrapElem(e, "Toggle")
    end

    function c:CreateSlider(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        return wrapElem(bx:Slider({
            Name = cfg.Name,
            Min = cfg.Min or 0, Max = cfg.Max or 100,
            Increment = cfg.Increment or 1,
            Default = cfg.Default or cfg.Min or 0,
            Suffix = cfg.Suffix or "",
            Callback = cfg.Callback,
            Flag = cfg.Flag,
        }), "Slider")
    end

    function c:CreateDropdown(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        return wrapElem(bx:Dropdown({
            Name = cfg.Name,
            Values = cfg.Values or {},
            Default = cfg.Default,
            Callback = cfg.Callback,
            Flag = cfg.Flag,
        }), "Dropdown")
    end

    function c:CreateMultiDropdown(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        return wrapElem(bx:Dropdown({
            Name = cfg.Name,
            Values = cfg.Values or {},
            Multi = true,
            Default = cfg.Default or {},
            Callback = cfg.Callback,
            Flag = cfg.Flag,
        }), "Dropdown")
    end

    function c:CreateColorPicker(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        return wrapElem(bx:ColorPicker({
            Name = cfg.Name,
            Default = cfg.Default or Color3.new(1, 1, 1),
            Callback = cfg.Callback,
            Flag = cfg.Flag,
        }), "ColorPicker")
    end

    function c:CreateKeybind(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        local key = cfg.Default
        if type(key) == "string" and key ~= "" and key ~= "None" then
            key = Enum.KeyCode[key] or nil
        else
            key = nil
        end
        return wrapElem(bx:Keybind({
            Name = cfg.Name,
            Default = key,
            Callback = cfg.Callback,
            Flag = cfg.Flag,
        }), "Keybind")
    end

    function c:CreateLabel(a)
        local cfg = norm(a)
        local text = type(a) == "string" and a or (cfg.Text or cfg.Name or "")
        local bx = box()
        if not bx then return nil end
        local e = wrapElem(bx:Label({ Text = text, Color = cfg.Color }), "Label")
        if e then
            e.CreateKeybind = function(self, name, kc) return c:CreateKeybind(name, kc) end
            e.CreateColorPicker = function(self, name, cc) return c:CreateColorPicker(name, cc) end
            e.AddKeyPicker = function(self, nameOrId, opts)
                opts = opts or {}
                return c:CreateKeybind(opts.Title or nameOrId, {
                    Name = opts.Title or nameOrId,
                    Default = opts.CurrentKeybind or opts.Default,
                    Callback = opts.Callback,
                })
            end
        end
        return e
    end

    function c:CreateInput(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        return wrapElem(bx:Input({
            Name = cfg.Name,
            Placeholder = cfg.Placeholder or "",
            Default = cfg.Default or "",
            Callback = cfg.Callback,
            Flag = cfg.Flag,
        }), "Input")
    end
    c.CreateTextBox = c.CreateInput

    function c:CreateParagraph(a, b)
        local cfg = norm(a, b)
        local bx = box()
        if not bx then return nil end
        return wrapElem(bx:Paragraph({
            Name = cfg.Title or cfg.Name or "",
            Content = cfg.Content or cfg.Text or "",
        }), "Paragraph")
    end

    function c:CreateDivider()
        local bx = box()
        if not bx then return nil end
        return bx:Divider()
    end

    function c:CreateDependencyBox()
        local pt = parentTab
        if not pt then return makeContainer(function() return box() end, nil) end
        local depBox = pt:AddLeftGroupbox({ Name = "Dependencies" })
        local dc = makeContainer(function() return depBox end, pt)
        dc.SetupDependencies = function() end
        return dc
    end

    function c:Set() end
    return c
end

-- Window wrapper
local function makeWindow(engWin)
    local w = {}
    w.ScreenGui = engWin.Gui
    w.Notify = function(self, cfg) engWin:Notify(cfg) end
    w.SetFooter = function(self, text) end
    w.SetCornerRadius = function(self, v)
        Library.CornerRadius = v
        pcall(function() Engine:SetCornerRadius(v) end)
    end
    w.SetSidebarWidth = function(self, v) pcall(function() engWin:SetSidebarWidth(v) end) end
    w.Minimize = function(self) engWin:Minimize() end
    w.Restore = function(self) engWin:Restore() end
    w.ToggleMinimize = function(self)
        if engWin.Minimized then engWin:Restore() else engWin:Minimize() end
    end
    w.IsMinimized = function(self) return engWin.Minimized end
    w.Destroy = function(self)
        engWin:Destroy()
        Unloaded = true
        Library.Unloaded = true
    end
    w.Toggle = function(self, v) engWin:Toggle(v) end
    w.SelectTab = function(self, tab)
        if tab and tab._engTab then engWin:SelectTab(tab._engTab) end
    end

    function w:CreateTab(a)
        local name = type(a) == "table" and (a.Name or a.Title or "Tab") or tostring(a or "Tab")
        local icon = type(a) == "table" and a.Icon or nil
        local engTab = engWin:Tab({ Name = name, Icon = icon })
        local firstBox = nil
        local tab = makeContainer(function()
            if not firstBox then firstBox = engTab:AddLeftGroupbox({ Name = name }) end
            return firstBox
        end, engTab)
        tab._engTab = engTab
        return tab
    end

    return w
end

-- ===================== Library methods =====================
function Library.CreateWindow(a, b)
    local cfg = sc(a, b) or {}
    local w = cfg.Width or 720
    local h = cfg.Height or 600
    local key = cfg.MinimizeKeybind or Enum.KeyCode.RightShift
    if type(key) == "string" then key = Enum.KeyCode[key] or Enum.KeyCode.RightShift end
    if not Engine.ThemePresets["Sakura Rose"] then
        Engine.ThemePresets["Sakura Rose"] = {
            Background = Color3.fromRGB(23, 14, 19),
            Surface = Color3.fromRGB(28, 17, 23),
            Surface2 = Color3.fromRGB(34, 21, 28),
            Surface3 = Color3.fromRGB(51, 33, 42),
            Stroke = Color3.fromRGB(48, 29, 39),
            StrokeHover = Color3.fromRGB(105, 65, 82),
            Accent = Color3.fromRGB(255, 183, 197),
            AccentDark = Color3.fromRGB(33, 13, 21),
            Text = Color3.fromRGB(247, 231, 237),
            Muted = Color3.fromRGB(147, 117, 128),
        }
    end
    pcall(function() Engine:SetTheme("Sakura Rose") end)
    local engWin = Engine:Window({
        Title = cfg.Name or "Ivory",
        Subtitle = cfg.LoadingSubtitle or "v1.4",
        Size = UDim2.fromOffset(w, h),
        Keybind = key,
        Home = false,
        Loading = false,
        UnsupportedExecutor = false,
    })
    EngineWin = engWin
    Library.ScreenGui = engWin.Gui
    local ww = makeWindow(engWin)
    table.insert(Library._windows, ww)
    return ww
end

function Library.Notify(a, b)
    local cfg = sc(a, b) or {}
    if not EngineWin then return end
    local typ = tostring(cfg.Type or "Info"):lower()
    if typ == "success" then typ = "Success"
    elseif typ == "warning" then typ = "Warning"
    elseif typ == "error" then typ = "Error"
    else typ = "Info" end
    EngineWin:Notify({
        Title = cfg.Title or cfg.Name or "Ivory",
        Content = cfg.Content or cfg.Text or "",
        Type = typ,
        Duration = cfg.Duration or 3,
    })
end

function Library.Unload(a)
    if Unloaded then return end
    Unloaded = true
    Library.Unloaded = true
    for _, fn in ipairs(OnUnloadFns) do pcall(fn) end
    if Library.UnloadCallback then pcall(Library.UnloadCallback) end
    if EngineWin then pcall(function() EngineWin:Destroy() end) end
end

function Library.Toggle(a)
    if EngineWin then EngineWin:Toggle() end
end

function Library.SetAccent(a, b)
    local col = sc(a, b)
    if typeof(col) == "Color3" then
        Library.Scheme.Accent = col
        pcall(function() Engine:SetTheme({ Accent = col }) end)
    end
end

function Library.SetDPIScale(a, b)
    local n = tonumber(sc(a, b)) or 100
    if EngineWin then pcall(function() EngineWin:SetUIScale(n / 100) end) end
end

function Library.SetNotifySide(a, b)
    Library.NotifySide = sc(a, b) or "Right"
end

function Library.SetMenuKeybind(a, b)
    local key = sc(a, b)
    if EngineWin and key then pcall(function() EngineWin:SetKeybind(key) end) end
end

function Library.ApplyThemePreset(a, b)
    local name = sc(a, b)
    if name then pcall(function() Engine:SetTheme(name) end) end
end

function Library.UpdateColorsUsingRegistry(a)
    local s = Library.Scheme
    pcall(function()
        Engine:SetTheme({ Accent = s.Accent, Background = s.Background, Text = s.Text })
    end)
    if s.CornerRadius then
        pcall(function() Engine:SetCornerRadius(s.CornerRadius) end)
        Library.CornerRadius = s.CornerRadius
    end
end

function Library.OnUnload(a, b)
    local fn = sc(a, b)
    if type(fn) == "function" then table.insert(OnUnloadFns, fn) end
end

function Library.SaveConfig(a, b)
    local name = sc(a, b)
    if EngineWin and name then return pcall(function() return EngineWin:SaveConfig(name) end) end
    return false
end

function Library.LoadConfig(a, b)
    local name = sc(a, b)
    if EngineWin and name then return pcall(function() return EngineWin:LoadConfig(name) end) end
    return false
end

function Library.ListConfigs()
    if EngineWin then return EngineWin:ListConfigs() end
    return {}
end

function Library.ResetAll() end

return Library end)() return a
